                            /** @description withOutcome ÷ past in %, the coverage of the outcome field; null without meetings */
                            outcomeCoverage: number | null;
                            /** @description Deals whose first meeting happened in the period and at least followUpDays ago (7), so the follow-up can be measured */
                            firstMeetings: number;
                            /** @description Of those, deals with a second meeting booked up to 7 days after the first */
                            followedUp: number;
                            /** @description followedUp ÷ firstMeetings in %, null below minimumBase */
                            followUpRate: number | null;
