                            id: string;
                            /** @description Nome do contato cadastrado quando vinculado, senão o visto nas conversas */
                            name: string | null;
                            /** @description Um e-mail do contato, quando conhecido */
                            email: string | null;
                            /** @description Telefone do contato cadastrado; nulo sem cadastro */
                            phone: string | null;
                            /**
                             * @description no_deal: contato cadastrado, sem negócio aberto; open_deal: com negócio aberto; unregistered: só nas conversas, sem cadastro de contato
                             * @enum {string}
                             */
