                            fileNamePattern: string;
                            /** @description Usar o layout padrão do Nexo: a escolha do admin de gerar sem o modelo da empresa. O agente só começa com um produto ativo no catálogo e com o modelo da empresa confirmado ou esta escolha ligada. Com um modelo confirmado, vale o modelo */
                            useDefaultLayout: boolean;
