                            unit: "count" | "cents" | "percent" | "days" | "number" | null;
                            /** @description Row key whose value splits the measure into one line per value, for a query with breakdownBy */
                            breakdownColumn: string | null;
                            /** @description Only for a calculated series: its formula (A / B); null for a measure of a query. A calculated series has no unit of its own, presentation.series[].unit gives its mask, and a point is null where a value it reads is missing or it divides by zero */
                            expression: string | null;
