                            connectorId: string;
                            versionSeq: number;
                            trigger: string;
                            /**
                             * @description O evento do Nexo que iniciou a execução, quando o gatilho é um evento
                             * @enum {string|null}
                             */
                            event: "company.created" | "company.updated" | "contact.created" | "contact.updated" | "deal.created" | "deal.updated" | "deal.won" | "lead.created" | "lead.updated" | "ticket.created" | "ticket.updated" | null;
                            /** @enum {string} */
                            mode: "live" | "dry_run";
                            /**
                             * @description Quanto da fonte um ensaio lê: uma amostra para depois das primeiras fatias, um completo vai até o fim; null numa execução ao vivo
                             * @enum {string|null}
                             */
                            rehearsalScope: "sample" | "full" | null;
                            /** @description Uma amostra que parou com mais para ler: limpa, mas publicar pede um ensaio completo */
                            cut: boolean;
                            /** @enum {string} */
                            status: "running" | "succeeded" | "partial" | "failed" | "timed_out";
                            failureReason: string | null;
                            /** Format: date-time */
                            startedAt: string;
                            /** Format: date-time */
                            finishedAt: string | null;
                            slices: number;
                            /** @description O que a execução fez em cada objeto do Nexo, guardado para sempre */
                            counters: {
                                [key: string]: {
                                    /** @description Valores consultados no Nexo */
                                    read: number;
                                    created: number;
                                    updated: number;
                                    /** @description Atualizações em que o núcleo não achou nada para mudar */
                                    skipped: number;
                                    /** @description Registros separados em quarentena */
                                    failed: number;
                                };
                            };
                            /**
                             * Format: uuid
                             * @description O conjunto de mudanças por onde passaram suas escritas no Nexo; null quando não gravou nada
                             */
                            changeSetId: string | null;
                            /** Format: date-time */
                            undoneAt: string | null;
                            /** @description Escritas externas que um ensaio só planejou */
                            plannedWrites: {
                                method: string;
                                host: string;
                                path: string;
                                /** @description A operação SOAP, para uma chamada SOAP: todas as operações de um serviço dividem um endereço */
                                operation?: string;
                                count: number;
                            }[];
                            /** @description Escritas no Nexo que um ensaio só planejou, contadas por registro */
